            "trans": "Tìm từ có phần gạch chân phát âm khác: house, round, cousin, mouth -> D. cousin phát âm là /ʌ/, các từ còn lại phát âm là /aʊ/.",
            "grammar": "Ngữ âm nguyên âm đôi /aʊ/ (house, round, mouth) so với nguyên âm ngắn /ʌ/ (cousin).",
            "tense": "Quy tắc phát âm Tiếng Anh.",
            "clue": "Đuôi 'ou': house /haʊs/, round /raʊnd/, mouth /maʊθ/ có âm /aʊ/, riêng cousin /ˈkʌzn/ phát âm là /ʌ/.",
            "evidence": "Phát âm IPA: house /haʊs/, round /raʊnd/, mouth /maʊθ/ -> nguyên âm đôi /aʊ/. Trong khi cousin /ˈkʌzn/ -> nguyên âm ngắn /ʌ/.",
            "praise": "🏆 Đỉnh cao phát âm! Em phân biệt nguyên âm đôi /aʊ/ và nguyên âm ngắn /ʌ/ rất tài tình!",
            "encourage": "🌱 'House, round, mouth' đều đọc là âm 'ao' (/aʊ/), riêng 'cousin' đọc là âm 'ớ' (/ʌ/) em nhé. Bấm làm lại câu này ngay nào!"
